import numpy as np
import pandas as pd
from xarray.core.indexes import PandasIndex

pidx = PandasIndex(pd.Index([0,2,4], name='x'), dim='x', coord_dtype=np.int64)

for case in [1,2]:
    try:
        if case==1:
            pidx.sel({'x':2}, method=7)
        else:
            pidx.sel({'x':{'left':2}})
    except Exception as e:
        print(case, type(e).__name__, str(e))
